CREATE TABLE IF NOT EXISTS customer_credit_profiles (customer_id INTEGER PRIMARY KEY REFERENCES customers(id), credit_limit DOUBLE PRECISION NOT NULL DEFAULT 0, max_term_days INTEGER NOT NULL DEFAULT 30, block_overdue BOOLEAN NOT NULL DEFAULT TRUE, tolerance_days INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_conditions (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, installment_days VARCHAR(300) NOT NULL DEFAULT '0', interest_percent_month DOUBLE PRECISION NOT NULL DEFAULT 0, fine_percent DOUBLE PRECISION NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sale_financial_plans (sale_id INTEGER PRIMARY KEY REFERENCES sales(id), payment_condition_id INTEGER NOT NULL REFERENCES payment_conditions(id));
CREATE TABLE IF NOT EXISTS receivable_installments (id SERIAL PRIMARY KEY, receivable_id INTEGER NOT NULL REFERENCES receivables(id), installment_number INTEGER NOT NULL, due_date DATE NOT NULL, original_amount DOUBLE PRECISION NOT NULL, paid_amount DOUBLE PRECISION NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'aberto', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_receivable_installment UNIQUE (receivable_id, installment_number));
CREATE TABLE IF NOT EXISTS collection_events (id SERIAL PRIMARY KEY, receivable_id INTEGER NOT NULL REFERENCES receivables(id), contact_type VARCHAR(40) NOT NULL, notes TEXT NOT NULL, next_contact_date DATE, responsible_id INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_receivable_installments_receivable_id ON receivable_installments(receivable_id);
CREATE INDEX IF NOT EXISTS ix_receivable_installments_due_date ON receivable_installments(due_date);
CREATE INDEX IF NOT EXISTS ix_collection_events_receivable_id ON collection_events(receivable_id);
